import React, { useEffect, useState } from 'react';
import {
  ResponsiveContainer,
  PieChart, Pie, Cell,
  BarChart, Bar, XAxis, YAxis, Tooltip
} from 'recharts';
import { loadDashboardData } from '../api/dashboard';

const RISK_COLORS = { safe: '#60a5fa', warning: '#facc15', danger: '#ef4444' };
const VULN_COLORS = { low: '#10b981', medium: '#f59e0b', high: '#ef4444' };

export default function DashboardPage() {
  const [data, setData]     = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const d = await loadDashboardData();
        setData(d);
      } catch (e) {
        setError(e.message);
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  if (loading) return <p className="text-center py-8">불러오는 중…</p>;
  if (error)   return <p className="text-red-500 text-center py-8">{error}</p>;

  const { summary, riskCounts, vulnCounts } = data;

  // 차트용 데이터 포맷
  const riskPieData = Object.entries(riskCounts)
    .map(([k,v]) => ({ name:k, value:v }))
    .filter(x=>x.value>0);

  const vulnPieData = Object.entries(vulnCounts)
    .map(([k,v]) => ({ name:k, value:v }))
    .filter(x=>x.value>0);

  return (
    <main style={{ maxWidth: 960, margin: '0 auto', padding: 24 }}>
      <h1 style={{ marginBottom: 32, fontSize: 32, fontWeight: 'bold' }}>
        포트스캐너 대시보드
      </h1>

      {/* 1) 요약 카드 */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 32 }}>
        <div
          style={{
            flex: 1,
            background: '#fff',
            boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
            borderRadius: 8,
            padding: 16,
          }}
        >
          <p style={{ margin: 0, color: '#6b7280', fontSize: 14 }}>
            전체 자산 수
          </p>
          <p style={{ margin: '8px 0 0', fontSize: 28, fontWeight: 'bold' }}>
            {summary.total_assets}
          </p>
        </div>

        <div
          style={{
            flex: 1,
            background: '#fff',
            boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
            borderRadius: 8,
            padding: 16,
          }}
        >
          <p style={{ margin: 0, color: '#6b7280', fontSize: 14 }}>
            위험 자산 수
          </p>
          <p style={{ margin: '8px 0 0', fontSize: 28, fontWeight: 'bold' }}>
            {summary.risky_assets}
          </p>
        </div>

        <div
          style={{
            flex: 1,
            background: '#fff',
            boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
            borderRadius: 8,
            padding: 16,
          }}
        >
          <p style={{ margin: 0, color: '#6b7280', fontSize: 14 }}>
            Critical CVE 건수
          </p>
          <p style={{ margin: '8px 0 0', fontSize: 28, fontWeight: 'bold' }}>
            {summary.critical_cves}
          </p>
        </div>
      </div>

      {/* 2) 위험도 분포 차트 (Pie) */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ margin: '0 0 16px', fontSize: 18, fontWeight: '600' }}>
          위험도 분포
        </h3>
        <div style={{ width: '100%', height: 250 }}>
          {/* 이전 Recharts 코드는 그대로 두시고, 래퍼만 inline 스타일 적용 */}
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>{/* … */}</PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 3) 취약점 심각도 분포 차트 (Pie) */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ margin: '0 0 16px', fontSize: 18, fontWeight: '600' }}>
          취약점 심각도 분포
        </h3>
        <div style={{ width: '100%', height: 250 }}>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>{/* … */}</PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 4) 자산별 열린 포트 수 (Bar) */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ margin: '0 0 16px', fontSize: 18, fontWeight: '600' }}>
          자산별 열린 포트 수
        </h3>
        <div style={{ width: '100%', height: 300 }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart>{/* … */}</BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 5) 포트 스캔 테이블 */}
      <div style={{ marginBottom: 24 }}>
        <h3 style={{ margin: '0 0 12px', fontSize: 18, fontWeight: '600' }}>
          포트 스캔 결과
        </h3>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ background: '#f3f4f6' }}>
              <th style={{ border: '1px solid #ddd', padding: 8 }}>Port</th>
              <th style={{ border: '1px solid #ddd', padding: 8 }}>Service</th>
              <th style={{ border: '1px solid #ddd', padding: 8 }}>Version</th>
            </tr>
          </thead>
          <tbody>
            {scanData.ports.map((p, idx) => (
              <tr key={idx}>
                <td style={{ border: '1px solid #ddd', padding: 8 }}>
                  {p.port}
                </td>
                <td style={{ border: '1px solid #ddd', padding: 8 }}>
                  {p.service}
                </td>
                <td style={{ border: '1px solid #ddd', padding: 8 }}>
                  {p.version}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 6) Canvas 차트 섹션 */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ margin: '0 0 12px', fontSize: 18, fontWeight: '600' }}>
          자산(Assets) 개수
        </h3>
        <canvas ref={assetChartRef} />

        <h3 style={{ margin: '24px 0 12px', fontSize: 18, fontWeight: '600' }}>
          취약점(Vulnerabilities) 심각도
        </h3>
        <canvas ref={vulnChartRef} />

        <h3 style={{ margin: '24px 0 12px', fontSize: 18, fontWeight: '600' }}>
          위험도(Risks) 분포
        </h3>
        <canvas ref={riskChartRef} />
      </div>
    </main>
  )
}
